SCREENS['g-help'] = () => `${gHead('Help')}<section class="card">${[['How do seats work?', 'Each bundle gives you a number of seats. Assigning a seat enrols one learner on one course. Unassigning may return the seat, depending on the Academy\'s rule.'], ['What does validity mean?', 'Your bundle\'s validity sets the access period for every seat you assign from it — it overrides the course default. Unused seats lapse when the bundle expires.'], ['How does paying by bank transfer work?', 'Choose "Pay by bank transfer (Academy approval)" when you buy. Finance approves the request, you pay by bank transfer quoting the reference, and seats are credited when payment is recorded. You get a receipt; no invoice document is issued.'], ['How do I renew a certificate?', 'Use "Renew" on an expiring certificate. It assigns a new seat on a bundle that includes the course.'], ['Why are some report details hidden?', 'The Academy decides which details are shared with agencies. Hidden columns are removed, not blurred.'], ['How do learners set their passwords?', 'When you add a learner, they get an email with a set-password link. You never see or set their password.']].map(([q, a]) => `<details class="wpc-faq"><summary>${q}</summary><p class="small">${a}</p></details>`).join('')}</section><section class="card"><h2>Contact the Academy</h2><p class="small">${academyContact()}</p></section>`;

/* ---------- Actions: learners ---------- */
function dupCheck(email, mobile) { const e = (email || '').toLowerCase(), m = (mobile || '').replace(/\s/g, ''); const all = agyRoster().concat(allLearners()); const hit = all.find(l => (e && l.email.toLowerCase() === e) || (m.length > 5 && l.mobile.replace(/\s/g, '') === m)); if (!hit) return null; return inRoster(hit.id) ? { mine: true, l: hit } : { elsewhere: true, l: hit }; }
ACT.agAddLearner = () => { const bs = agyBundles().filter(b => bStatus(b) !== 'Expired' && left(b) > 0); openModal({ title: 'Add learner', size: 'lg', body: `<div class="form-grid"><div class="field full"><label for="gl-n">Full name</label><input class="input" id="gl-n"></div><div class="field"><label for="gl-e">Email</label><input class="input" id="gl-e" type="email" data-oninput="agDup"><span id="gl-de"></span></div><div class="field"><label for="gl-m">Mobile</label><input class="input" id="gl-m" type="tel" data-oninput="agDup"><span id="gl-dm"></span></div><div class="field"><label for="gl-r">Staff reference</label><input class="input" id="gl-r"></div>
  <div class="field full"><label for="gl-s">Assign a seat now (optional)</label><select class="select" id="gl-s"><option value="">Not now</option>${bs.flatMap(b => b.courses.map(c => `<option value="${b.id}|${esc(c)}">${esc(c)} — ${esc(b.name)} (${left(b)} left)</option>`)).join('')}</select></div></div><p class="xs muted">${ic('lock', 12)} You won't see or set the learner's password. We email them a set-password link.</p>`,
  actions: [{ label: 'Cancel' }, { label: 'Create learner', cls: 'btn-primary', fn: () => {
    const n = mval('#gl-n'), e = mval('#gl-e'), m = mval('#gl-m'); if (!n) { fieldErr('#gl-n', 'Enter the learner\'s name'); return false; } if (!/^\S+@\S+\.\S+$/.test(e)) { fieldErr('#gl-e', 'Enter a valid email address'); return false; }
    const d = dupCheck(e, m); if (d && d.mine) { fieldErr('#gl-e', 'Already in your learners'); return false; } if (d && d.elsewhere) { const em = e; setTimeout(() => agLinkReq(em), 0); return; }
    const l = agyCreateLearner(n, e, m, 'Created', mval('#gl-r')); const s = mval('#gl-s'); if (s) { const [bid, c] = s.split('|'); agyDoAssign(ADMIN.bundles.find(b => b.id === bid), c, [l.id]); }
    render(); toast(`Learner created — set-password link sent to ${esc(e)}.${s ? ' Seat assigned.' : ''}`);
  } }] }); };
INP.agDup = el => { const isE = el.id === 'gl-e', box = $(isE ? '#gl-de' : '#gl-dm'), d = el.value.trim().length > 5 ? dupCheck(isE ? el.value.trim() : '', isE ? '' : el.value.trim()) : null; box.innerHTML = !d ? '' : d.mine ? `<span class="err">${ic('alert', 14)}Already in your learners — <button type="button" class="linklike" data-act="agOpenDup" data-id="${d.l.id}">open</button></span>` : `<span class="err" style="color:var(--amber)">${ic('info', 14)}An account with this ${isE ? 'email' : 'mobile'} already exists. <button type="button" class="linklike" data-act="agLinkFromAdd">Request to link this learner to your agency?</button></span>`; };
ACT.agOpenDup = el => { closeModal(); go('g-learner', { id: el.dataset.id }); };
ACT.agLinkFromAdd = () => { const e = mval('#gl-e') || mval('#gl-m'); closeModal(); agLinkReq(e); };
function agLinkReq(emailOrMobile) { const cs = [...new Set(agyBundles().filter(b => bStatus(b) !== 'Expired').flatMap(b => b.courses))]; openModal({ title: 'Link existing learner', body: `<p class="small">An account with <strong>${esc(emailOrMobile)}</strong> already exists on Illumin Academy. We can't show you any of its details. The learner gets an email asking them to approve or decline. The request expires after ${CONSENT_DAYS} days without a response.</p><div class="field"><label for="gk-c">Course you want to sponsor</label><select class="select" id="gk-c">${cs.map(c => `<option>${esc(c)}</option>`).join('')}</select></div><div class="field"><label for="gk-r">Note (optional)</label><textarea class="textarea" id="gk-r" placeholder="For example: this person now works for us"></textarea></div><p class="xs muted">If the learner is already enrolled on this course, the Academy also approves the link after the learner consents.</p>`, actions: [{ label: 'Cancel' }, { label: 'Send consent request', cls: 'btn-primary', fn: () => { const res = agyRaiseLink(emailOrMobile, mval('#gk-r'), mval('#gk-c')); if (res && res.err) { fieldErr('#gk-c', res.err); return false; } render(); toast('Consent request sent to the learner.'); } }] }); }
function agyRaiseLink(key, r, course) { const d = dupCheck(key.includes('@') ? key : '', key.includes('@') ? '' : key); return agyRequestConsent(d ? d.l : null, key, course || (agyBundles()[0] || { courses: ['—'] }).courses[0], r || ''); }
function agyCreateLearner(n, e, m, how, ref) { const uae = AG().region === 'UAE'; const l = { id: 'IA-L-' + (42000 + ADMIN.learners.filter(x => !x.g31).length * 7), name: n, email: e, mobile: m || '—', agency: AGN(), courses: [], acct: 'Pending Verification', rec: 'Active', region: uae ? 'UAE' : 'UK', last: now().toISOString(), flags: [], dob: '—', address: '—', postcode: '—', country: uae ? 'United Arab Emirates' : 'United Kingdom', joined: fd(now().toISOString()), referral: 'Created by agency', cur: 'GBP' }; ADMIN.learners.unshift(l); STORE.agy.meta[l.id] = { how, added: agNow().toISOString(), staffRef: ref || '—' }; STORE.agy.lmails.unshift({ id: 'LM-' + (100 + STORE.agy.lmails.length), lid: l.id, name: n, email: e, agency: AGN(), sent: now().toISOString(), used: false }); ADMIN.audit.unshift({ id: 'AU-' + (9950 + ADMIN.audit.length), actor: AG_CONTACT(), role: 'Agency Administrator', at: now().toISOString(), module: 'Learners', entity: l.id, action: 'Learner created by agency', before: '—', after: 'Pending Verification', reason: AGN(), ip: '86.12.44.10' }); return l; }
