const IMP_ROWS = () => [['Ella Watson', 'ella.watson@uk.example', '+44 7700 900901', 'valid'], ['Ben Shaw', 'ben.shaw@uk.example', '+44 7700 900902', 'valid'], ['Tia Morgan', 'tia.morgan@uk.example', '+44 7700 900903', 'valid'], [agyRoster()[0] ? agyRoster()[0].name : 'Bethany Cole', agyRoster()[0] ? agyRoster()[0].email : 'x@x', '+44 7700 900904', 'dupMine'], ['Aisha Rahman', 'aisha.rahman@gmail.example', '+44 7700 900188', 'elsewhere'], ['Peter Grant', 'peter.grant@', '+44 7700 900906', 'error:Invalid email address'], ['Noura Saeed', 'noura.saeed@uk.example', '', 'error:Mobile is required'], ['Kieran Walsh', 'kieran.walsh@careplus-staff.example', '+44 7700 900908', 'valid']];
ACT.agImport = () => { S.agy.imp = S.agy.imp || { step: 1, map: { name: 'Full name', email: 'Email address', mobile: 'Mobile' }, link: {}, bundle: '', course: '', mode: 'all' }; agImpDraw(); };
function agImpDraw() {
  const st = S.agy.imp, rows = IMP_ROWS(), valid = rows.filter(r => r[3] === 'valid'), bs = agyBundles().filter(b => bStatus(b) !== 'Expired' && left(b) > 0), b = bs.find(x => x.id === st.bundle);
  const lab = { valid: chip('Valid', 'green'), dupMine: chip('Already in your learners', 'grey'), elsewhere: chip('Exists elsewhere', 'amber') };
  const body = [
    `<ol class="small"><li>Download the template and add one learner per row.</li><li>Upload the file.</li></ol><div class="row"><button class="btn btn-sm" data-act="fakeDl" data-f="agency-learner-template.csv">${ic('download', 14)}Download template</button></div><label class="drop" for="gi-f">${ic('upload', 22)}<span><strong>Choose a CSV file</strong> or drag it here</span></label><input type="file" id="gi-f" class="sr" accept=".csv" data-onchange="agImpPick"><button class="btn btn-sm" data-act="agImpSample">Use sample file (demo)</button>${st.file ? `<p class="small">${ic('doc', 14)} ${esc(st.file)} · 8 rows</p>` : ''}`,
    `<p class="small">Match your file's columns to ours.</p>${[['name', 'Full name'], ['email', 'Email'], ['mobile', 'Mobile'], ['ref', 'Staff reference']].map(([k, l]) => `<div class="field"><label for="gm-${k}">${l}</label><select class="select" id="gm-${k}" data-onchange="agImpMap" data-k="${k}">${['— Not in file —', 'Full name', 'Email address', 'Mobile', 'Employee no.'].map(o => `<option ${st.map[k] === o ? 'selected' : ''}>${o}</option>`).join('')}</select></div>`).join('')}`,
    `<div class="tbl-wrap"><table class="tbl dense"><thead><tr><th>Row</th><th>Name</th><th>Email</th><th>Result</th></tr></thead><tbody>${rows.map((r, k) => `<tr><td>${k + 2}</td><td>${esc(r[0])}</td><td class="small">${esc(r[1])}</td><td>${r[3].startsWith('error') ? chip('Error', 'red') + ` <span class="xs">${esc(r[3].slice(6))}</span>` : lab[r[3]]}${r[3] === 'elsewhere' ? ` <label class="check xs"><input type="checkbox" ${st.link[k] ? 'checked' : ''} data-onchange="agImpLink" data-i="${k}">Request link</label>` : ''}</td></tr>`).join('')}</tbody></table></div><p class="small">${valid.length} valid · 1 already yours · 1 exists elsewhere · 2 errors</p>`,
    `<p class="small">Optionally assign a seat to the ${valid.length} valid learners.</p><div class="field"><label for="gi-b">Bundle and course</label><select class="select" id="gi-b" data-onchange="agImpSeat"><option value="">Skip — no seats now</option>${bs.flatMap(x => x.courses.map(c => `<option value="${x.id}|${esc(c)}" ${st.bundle === x.id && st.course === c ? 'selected' : ''}>${esc(c)} — ${esc(x.name)} (${left(x)} left)</option>`)).join('')}</select></div>${b ? `<p class="small">Seats needed: <strong>${valid.length}</strong> · available: <strong>${left(b)}</strong></p>${valid.length > left(b) ? `<div class="note b-amber">${ic('alert')}<div class="small"><strong>Not enough seats.</strong><label class="check"><input type="radio" name="gi-m" value="first" ${st.mode === 'first' ? 'checked' : ''} data-onchange="agImpMode">Assign to the first ${left(b)}</label><label class="check"><input type="radio" name="gi-m" value="buy" ${st.mode === 'buy' ? 'checked' : ''} data-onchange="agImpMode">Buy more seats first</label></div></div>` : ''}` : ''}`,
    st.result ? `<div class="kpis">${kpi('Created', st.result.created)}${kpi('Link requests raised', st.result.links)}${kpi('Failed', st.result.failed)}${kpi('Seats assigned', st.result.seats)}</div><button class="btn btn-sm" data-act="fakeDl" data-f="import-errors.csv">${ic('download', 14)}Download error report</button>` : '',
  ][st.step - 1];
  const labels = ['Upload', 'Map columns', 'Check rows', 'Assign seats (optional)', 'Result'];
  openModal({ title: `Bulk import — step ${st.step} of 5`, sub: labels[st.step - 1], size: 'lg', body: `<ol class="stepper">${labels.map((l, k) => `<li class="step ${k + 1 < st.step ? 'done' : k + 1 === st.step ? 'cur' : ''}"><span class="dot">${k + 1}</span><span class="s-l">${l}</span></li>`).join('')}</ol>${body}`,
    actions: st.step === 5 ? [{ label: 'Done', cls: 'btn-primary', fn: () => { S.agy.imp = null; render(); } }] : [st.step === 1 ? { label: 'Cancel', fn: () => { S.agy.imp = null; } } : { label: 'Back', fn: () => { st.step--; agImpDraw(); return false; } }, { label: st.step === 4 ? 'Create learners' : 'Next', cls: 'btn-primary', fn: () => {
      if (st.step === 1 && !st.file) { toast('Choose a CSV file first.', 'err'); return false; }
      if (st.step === 4) { if (st.mode === 'buy' && b && valid.length > left(b)) { closeModal(); go('g-buy'); toast('Buy more seats, then come back to Bulk import — your file and mapping are kept.', 'info'); return; } const made = valid.map(r => agyCreateLearner(r[0], r[1], r[2], 'Bulk import')); let seats = 0; if (b) { const ids = made.map(l => l.id).slice(0, left(b)); agyDoAssign(b, st.course, ids, true); seats = ids.length; } const links = Object.keys(st.link).filter(k => st.link[k]).map(k => agyRaiseLink(rows[k][1], 'Bulk import — this learner now works for us', st.course)).length; st.result = { created: made.length, links, failed: rows.filter(r => r[3].startsWith('error')).length + rows.filter(r => r[3] === 'dupMine').length, seats }; }
      st.step++; agImpDraw(); return false; } }] });
}
