  const msg = { Paid: [`${ic('check', 28)}`, 'Payment successful', `Receipt ${'RCP-' + ref.slice(-5)} · ${qty} seats are in your account now.`], Failed: [ic('alert', 28), 'Payment failed', 'Your card was declined. Nothing was charged. Try again or use another card.'], Cancelled: [ic('x', 28), 'Payment cancelled', 'You cancelled the payment. Nothing was charged.'], Pending: [ic('clock', 28), 'Confirming your payment', 'This can take a few minutes. We\'ll notify you when seats are credited.'], 'Timed out': [ic('clock', 28), 'Payment timed out', 'We didn\'t hear back from your bank in time. Nothing was charged — try again.'] }[st];
